{"path":"/root/solve_workbook.py","content":"from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from pathlib import Path
import shutil
import re

SRC = Path('/root/data/workbook.xlsx')
OUT = Path('/root/output/result.xlsx')
OUT.parent.mkdir(parents=True, exist_ok=True)

print('=== Setup check ===')
try:
    import openpyxl
    print(f'openpyxl version: {openpyxl.__version__}')
except Exception as exc:
    raise RuntimeError(f'openpyxl is required but could not be imported: {exc}')
print(f'Source workbook: {SRC} exists={SRC.exists()}')

# IMPORTANT: do not use data_only=True; formulas must be preserved.
wb = load_workbook(SRC, data_only=False)
print('\n=== Workbook sheets ===')
print(wb.sheetnames)
if 'Task' not in wb.sheetnames or 'Data' not in wb.sheetnames:
    raise RuntimeError(f'Expected sheets Task and Data, found {wb.sheetnames}')
ws_task = wb['Task']
ws_data = wb['Data']

# Helpers
BLOCKS = [(12, 17), (19, 24), (26, 31)]
YEAR_COLS = list(range(8, 13))  # H:L

def fmt(v):
    return '<empty>' if v is None else repr(v)

def row_values(ws, row, start_col, end_col):
    return [ws.cell(row=row, column=c).value for c in range(start_col, end_col + 1)]

def nonempty_in_row(ws, row, start_col=1, end_col=None):
    if end_col is None:
        end_col = ws.max_column
    out = []
    for c in range(start_col, end_col + 1):
        v = ws.cell(row=row, column=c).value
        if v is not None:
            out.append((get_column_letter(c), v))
    return out

def normalize_metric(s):
    if s is None:
        return ''
    s = str(s).lower()
    s = re.sub(r'[^a-z0-9]+', ' ', s)
    return re.sub(r'\s+', ' ', s).strip()

print('\n=== Step 0: Task sheet inspection ===')
for start, end in BLOCKS:
    print(f'Task column D rows {start}-{end} series codes:')
    for r in range(start, end + 1):
        print(f'  D{r}: {fmt(ws_task.cell(r, 4).value)}')

print('Task row 10 columns H-L years:')
for c in YEAR_COLS:
    print(f'  {get_column_letter(c)}10: {fmt(ws_task.cell(10, c).value)}')

years = [ws_task.cell(10, c).value for c in YEAR_COLS]
if any(y is None for y in years):
    raise RuntimeError(f'Expected years in H10:L10, got {years}')

print('\nTask H35:L40 current contents:')
for r in range(35, 41):
    print(f'  row {r}: {row_values(ws_task, r, 8, 12)}')
print('Task H42:L47 current contents:')
for r in range(42, 48):
    print(f'  row {r}: {row_values(ws_task, r, 8, 12)}')
print('Task H50:L50 current contents:')
print(f'  row 50: {row_values(ws_task, 50, 8, 12)}')

print('\nTask labels near rows 35-40 (columns A-G):')
for r in range(35, 41):
    print(f'  row {r}: {nonempty_in_row(ws_task, r, 1, 7)}')
print('Task labels near rows 42-47 (columns A-G):')
for r in range(42, 48):
    print(f'  row {r}: {nonempty_in_row(ws_task, r, 1, 7)}')
print('Task label row 50 (columns A-G):')
print(f'  row 50: {nonempty_in_row(ws_task, 50, 1, 7)}')

print('\nTask metric/block labels around rows 11, 18, 25 (columns A-G plus row samples):')
metric_header_rows = {1: 11, 2: 18, 3: 25}
for i, header_row in metric_header_rows.items():
    print(f'  block {i}, possible header row {header_row}: {nonempty_in_row(ws_task, header_row, 1, 7)}')
    print(f'    first data row {BLOCKS[i-1][0]} labels A-G: {nonempty_in_row(ws_task, BLOCKS[i-1][0], 1, 7)}')

print('\n=== Step 0: Data sheet inspection rows 21-38 ===')
print(f'Data sheet max_row={ws_data.max_row}, max_column={ws_data.max_column}')
# Print non-empty cells in rows 19-38 to reveal header row(s) and series/year layout.
for r in range(19, 39):
    vals = nonempty_in_row(ws_data, r, 1, min(ws_data.max_column, 80))
    if vals:
        print(f'  Data row {r}: {vals}')

# Detect the exact Data layout.
all_series_codes = []
for start, end in BLOCKS:
    for r in range(start, end + 1):
        v = ws_task.cell(r, 4).value
        if v is not None:
            all_series_codes.append(v)
unique_series_codes = list(dict.fromkeys(all_series_codes))
print(f'\nSeries codes gathered from Task D blocks ({len(unique_series_codes)} unique): {unique_series_codes}')

# Candidate series-code columns are columns in Data rows 21:38 whose values match the Task series codes.
code_match_counts = []
for c in range(1, ws_data.max_column + 1):
    count = 0
    matched = []
    for r in range(21, 39):
        v = ws_data.cell(r, c).value
        if v in unique_series_codes:
            count += 1
            matched.append(v)
    if count:
        code_match_counts.append((c, count, matched[:5]))
print('Data candidate series-code columns in rows 21-38 (col, match_count, sample_matches):')
for c, count, sample in code_match_counts:
    print(f'  {get_column_letter(c)} ({c}): {count}, sample={sample}')
if not code_match_counts:
    raise RuntimeError('Could not find any Data column in rows 21-38 matching Task series codes')
series_col = max(code_match_counts, key=lambda x: x[1])[0]
series_col_letter = get_column_letter(series_col)

# Candidate year header row/columns: rows 1:25 and columns to the right of the series code.
# Prefer a row immediately above data rows (often 20) that contains all Task years.
year_candidates = []
for r in range(1, 26):
    found_cols = []
    for y in years:
        for c in range(1, ws_data.max_column + 1):
            if ws_data.cell(r, c).value == y:
                found_cols.append(c)
                break
    if len(found_cols) == len(years):
        year_candidates.append((r, found_cols))
print('Data candidate year header rows (row, columns for H:L years):')
for r, cols in year_candidates:
    print(f'  row {r}: {[get_column_letter(c) for c in cols]}')
if not year_candidates:
    raise RuntimeError(f'Could not find a Data header row containing all years {years}')
# Choose the candidate closest to row 21 and generally above it.
year_header_row, year_cols_found = min(year_candidates, key=lambda rc: (abs(21 - rc[0]), rc[0] > 21))
first_year_col = min(year_cols_found)
last_year_col = max(year_cols_found)
# Extend the year data range to contiguous year columns if appropriate, but the MATCH range can be just first:last.
# Ensure selected range contains the requested year headers.
year_header_values = [ws_data.cell(year_header_row, c).value for c in range(first_year_col, last_year_col + 1)]
print(f'Chosen Data layout: series codes in Data!${series_col_letter}$21:${series_col_letter}$38; years in Data!${get_column_letter(first_year_col)}${year_header_row}:${get_column_letter(last_year_col)}${year_header_row}')
print(f'Header values in chosen year range: {year_header_values}')
print('Row 21-38 code/value sample for chosen Data layout:')
for r in range(21, 39):
    print(f'  row {r}: code={fmt(ws_data.cell(r, series_col).value)}, values={row_values(ws_data, r, first_year_col, last_year_col)}')

# Determine which block corresponds to Successful API Requests, Failed API Requests, Compute Capacity.
print('\n=== Step 2 metric block identification ===')
block_metric_text = {}
for idx, (start, end) in enumerate(BLOCKS, start=1):
    pieces = []
    for r in range(start - 2, start):
        for c in range(1, 8):
            v = ws_task.cell(r, c).value
            if v is not None:
                pieces.append(str(v))
    # Include D codes? no, only labels A-G nearby; include row start A-C/E-G region labels if helpful.
    for c in range(1, 8):
        if c == 4:
            continue
        v = ws_task.cell(start, c).value
        if v is not None:
            pieces.append(str(v))
    text = ' | '.join(pieces)
    block_metric_text[idx] = text
    print(f'  Block {idx} rows {start}-{end}: text={text!r}, normalized={normalize_metric(text)!r}')

metric_to_block = {}
for idx, text in block_metric_text.items():
    n = normalize_metric(text)
    if 'successful' in n and ('api' in n or 'request' in n):
        metric_to_block['successful'] = idx
    if 'failed' in n and ('api' in n or 'request' in n):
        metric_to_block['failed'] = idx
    if 'compute' in n and 'capacity' in n:
        metric_to_block['capacity'] = idx

# Conservative fallback by apparent common layout if labels are absent.
if set(metric_to_block) != {'successful', 'failed', 'capacity'}:
    print('WARNING: Could not identify all metrics from labels. Falling back to common layout: block 1=successful, block 2=failed, block 3=capacity.')
    metric_to_block.setdefault('successful', 1)
    metric_to_block.setdefault('failed', 2)
    metric_to_block.setdefault('capacity', 3)
print(f'Identified metric_to_block: {metric_to_block}')

block_rows = {idx: BLOCKS[idx - 1] for idx in (1, 2, 3)}
success_start = block_rows[metric_to_block['successful']][0]
failed_start = block_rows[metric_to_block['failed']][0]
capacity_start = block_rows[metric_to_block['capacity']][0]

# Locate statistic labels rows 42-47.
print('\n=== Step 3 statistic row identification ===')
stat_rows = {}
for r in range(42, 48):
    label_text = ' '.join(str(v) for _, v in nonempty_in_row(ws_task, r, 1, 7))
    n = normalize_metric(label_text)
    print(f'  row {r} label text={label_text!r}, normalized={n!r}')
    if 'min' in n and 'max' not in n:
        stat_rows['minimum'] = r
    elif 'max' in n:
        stat_rows['maximum'] = r
    elif 'median' in n:
        stat_rows['median'] = r
    elif 'mean' in n or 'average' in n:
        stat_rows['mean'] = r
    elif ('25' in n or 'twenty fifth' in n or '1st quartile' in n or 'q1' in n) and '75' not in n:
        stat_rows['p25'] = r
    elif '75' in n or 'third quartile' in n or 'q3' in n:
        stat_rows['p75'] = r
# Fill by task's specified row order if labels were not machine-identified.
row_order_defaults = {'minimum': 42, 'maximum': 43, 'median': 44, 'mean': 45, 'p25': 46, 'p75': 47}
for k, r in row_order_defaults.items():
    stat_rows.setdefault(k, r)
print(f'Statistic formula rows: {stat_rows}')

print('\n=== Step 1: writing lookup formulas to H12:L17, H19:L24, H26:L31 ===')
lookup_formula_samples = []
value_range = f"Data!${get_column_letter(first_year_col)}$21:${get_column_letter(last_year_col)}$38"
code_range = f"Data!${series_col_letter}$21:${series_col_letter}$38"
header_range = f"Data!${get_column_letter(first_year_col)}${year_header_row}:${get_column_letter(last_year_col)}${year_header_row}"
for start, end in BLOCKS:
    for r in range(start, end + 1):
        for c in YEAR_COLS:
            col = get_column_letter(c)
            formula = f"=INDEX({value_range}, MATCH($D{r}, {code_range}, 0), MATCH({col}$10, {header_range}, 0))"
            ws_task.cell(r, c).value = formula
            if len(lookup_formula_samples) < 6:
                lookup_formula_samples.append((f'{col}{r}', formula))
print(f'Lookup ranges: value_range={value_range}, code_range={code_range}, header_range={header_range}')
for addr, formula in lookup_formula_samples:
    print(f'  {addr}: {formula}')

print('\n=== Step 2: writing Net reliability gap formulas to H35:L40 ===')
gap_formula_samples = []
for offset, r in enumerate(range(35, 41)):
    s_row = success_start + offset
    f_row = failed_start + offset
    cap_row = capacity_start + offset
    for c in YEAR_COLS:
        col = get_column_letter(c)
        formula = f"=({col}{s_row}-{col}{f_row})/{col}{cap_row}*100"
        ws_task.cell(r, c).value = formula
        if len(gap_formula_samples) < 6:
            gap_formula_samples.append((f'{col}{r}', formula))
for addr, formula in gap_formula_samples:
    print(f'  {addr}: {formula}')
print(f'Net reliability mapping: successful rows start {success_start}, failed rows start {failed_start}, capacity rows start {capacity_start}')

print('\n=== Step 3: writing summary statistic formulas to H42:L47 ===')
stat_formula_samples = []
for c in YEAR_COLS:
    col = get_column_letter(c)
    formulas = {
        'minimum': f'=MIN({col}35:{col}40)',
        'maximum': f'=MAX({col}35:{col}40)',
        'median': f'=MEDIAN({col}35:{col}40)',
        'mean': f'=AVERAGE({col}35:{col}40)',
        'p25': f'=PERCENTILE.INC({col}35:{col}40, 0.25)',
        'p75': f'=PERCENTILE.INC({col}35:{col}40, 0.75)',
    }
    for key, formula in formulas.items():
        r = stat_rows[key]
        ws_task.cell(r, c).value = formula
        if len(stat_formula_samples) < 8:
            stat_formula_samples.append((f'{col}{r}', formula))
for addr, formula in stat_formula_samples:
    print(f'  {addr}: {formula}')

print('\n=== Step 4: writing weighted mean formulas to H50:L50 ===')
weighted_samples = []
capacity_end = capacity_start + 5
for c in YEAR_COLS:
    col = get_column_letter(c)
    formula = f'=SUMPRODUCT({col}35:{col}40, {col}{capacity_start}:{col}{capacity_end})/SUM({col}{capacity_start}:{col}{capacity_end})'
    ws_task.cell(50, c).value = formula
    weighted_samples.append((f'{col}50', formula))
for addr, formula in weighted_samples:
    print(f'  {addr}: {formula}')

print('\n=== Step 5-6: saving workbook ===')
wb.save(OUT)
print(f'Saved result to {OUT}')

print('\n=== Step 7: verification ===')
verify_wb = load_workbook(OUT, data_only=False)
print(f'Reopened workbook sheets: {verify_wb.sheetnames}')
if verify_wb.sheetnames != wb.sheetnames:
    raise RuntimeError(f'Sheet names changed: before={wb.sheetnames}, after={verify_wb.sheetnames}')
vtask = verify_wb['Task']

def assert_formula_block(start_row, end_row, start_col=8, end_col=12, label='block'):
    missing = []
    not_formula = []
    samples = []
    for r in range(start_row, end_row + 1):
        for c in range(start_col, end_col + 1):
            v = vtask.cell(r, c).value
            addr = f'{get_column_letter(c)}{r}'
            if v is None or v == '':
                missing.append(addr)
            elif not (isinstance(v, str) and v.startswith('=')):
                not_formula.append((addr, v))
            elif len(samples) < 5:
                samples.append((addr, v))
    if missing or not_formula:
        raise RuntimeError(f'{label} formula verification failed: missing={missing}, not_formula={not_formula[:10]}')
    print(f'  {label}: OK, sample={samples}')

assert_formula_block(12, 17, label='H12:L17 lookup block 1')
assert_formula_block(19, 24, label='H19:L24 lookup block 2')
assert_formula_block(26, 31, label='H26:L31 lookup block 3')
assert_formula_block(35, 40, label='H35:L40 net reliability gap')
assert_formula_block(42, 47, label='H42:L47 summary statistics')
assert_formula_block(50, 50, label='H50:L50 weighted mean')

# Additional reference checks for formulas.
checks = {
    'H12 lookup uses Task D and H10': ('$D12', 'H$10', 'INDEX(', 'MATCH('),
    'H35 gap references metric rows': (f'H{success_start}', f'H{failed_start}', f'H{capacity_start}'),
    'H42 min range': ('MIN(H35:H40)',),
    'H50 weighted range': (f'SUMPRODUCT(H35:H40, H{capacity_start}:H{capacity_end})', f'SUM(H{capacity_start}:H{capacity_end})'),
}
for desc, required_parts in checks.items():
    cell = {'H12 lookup uses Task D and H10': 'H12', 'H35 gap references metric rows': 'H35', 'H42 min range': 'H42', 'H50 weighted range': 'H50'}[desc]
    v = vtask[cell].value
    ok = all(part in v for part in required_parts)
    print(f'  Check {desc}: cell {cell}={v!r}, ok={ok}')
    if not ok:
        raise RuntimeError(f'Formula reference check failed for {desc}: {v!r}')

print('\nSample formulas from each requested area:')
for addr in ['H12', 'L17', 'H19', 'L24', 'H26', 'L31', 'H35', 'L40', 'H42', 'H43', 'H44', 'H45', 'H46', 'H47', 'H50', 'L50']:
    print(f'  {addr}: {vtask[addr].value}')

print('\nSUCCESS: workbook populated and verified.')
